function Read-Editor([Windows.Automation.AutomationElement]$editor){([Windows.Automation.TextPattern]$editor.GetCurrentPattern([Windows.Automation.TextPattern]::Pattern)).DocumentRange.GetText(-1)}
$ErrorActionPreference='Stop';$tag=[Guid]::NewGuid().ToString('N').Substring(0,8);$path=$global:MediaDir+'\M5-offline-'+$tag+'.txt';[IO.File]::WriteAllText($path,'');Start-Process notepad.exe -ArgumentList ('"'+$path+'"')
$watch=[Diagnostics.Stopwatch]::StartNew();$window=$null
while(-not$window-and$watch.ElapsedMilliseconds-lt10000){$window=@([Windows.Automation.AutomationElement]::RootElement.FindAll([Windows.Automation.TreeScope]::Children,[Windows.Automation.Condition]::TrueCondition)|Where-Object {$_.Current.Name-match$tag}|Select-Object -First 1)[0];if(-not$window){Start-Sleep -Milliseconds 100}}
if(-not$window){throw 'Notepad fixture missing'};$h=[IntPtr]$window.Current.NativeWindowHandle
$tab=@($window.FindAll([Windows.Automation.TreeScope]::Descendants,[Windows.Automation.Condition]::TrueCondition)|Where-Object {$_.Current.ControlType-eq[Windows.Automation.ControlType]::TabItem-and$_.Current.Name-match$tag}|Select-Object -First 1)[0]
if($tab){([Windows.Automation.SelectionItemPattern]$tab.GetCurrentPattern([Windows.Automation.SelectionItemPattern]::Pattern)).Select()}
$editor=$null;$watch=[Diagnostics.Stopwatch]::StartNew();do{try{$editor=@($window.FindAll([Windows.Automation.TreeScope]::Descendants,[Windows.Automation.Condition]::TrueCondition)|Where-Object {$_.Current.ControlType-eq[Windows.Automation.ControlType]::Document-and-not$_.Current.IsOffscreen}|Select-Object -First 1)[0]}catch{};if(-not$editor){Start-Sleep -Milliseconds 100}}while(-not$editor-and$watch.ElapsedMilliseconds-lt5000);if(-not$editor){throw 'Notepad editor not ready'};$editor.SetFocus();$watch=[Diagnostics.Stopwatch]::StartNew();do{try{Activate-LabEditor $h}catch{};if((Get-LabFocus).hwnd-eq$h.ToInt64()){break};Start-Sleep -Milliseconds 200}while($watch.ElapsedMilliseconds-lt3000);if((Get-LabFocus).hwnd-ne$h.ToInt64()){throw 'Notepad activation failed after its editor was ready'};if($tab){([Windows.Automation.SelectionItemPattern]$tab.GetCurrentPattern([Windows.Automation.SelectionItemPattern]::Pattern)).Select();Start-Sleep -Milliseconds 200};$editor=Find-Editor $h;$editor.SetFocus();$before=Read-Editor $editor;if($before.Trim().Length-ne0){throw 'Notepad fixture is not empty'}
$focus=Get-LabFocus;$browsersBefore=@(Get-Process msedge,msedgewebview2 -ErrorAction SilentlyContinue|Select-Object Id,ProcessName);$start=Run-MediaCli 'start'
$watch=[Diagnostics.Stopwatch]::StartNew();do{Start-Sleep -Milliseconds 100;$state=(Run-MediaCli 'status').stdout|ConvertFrom-Json}while($state.status-ne'recording'-and$watch.ElapsedMilliseconds-lt10000);if($state.status-ne'recording'){throw 'Offline recording did not start'}
$quitRecording=Run-MediaCli 'quit';if($quitRecording.exit-eq0){throw 'Quit accepted during recording'};$owner=[LabDriver]::ByClass('KoettOwnerWindow');$sessionAllowed=[LabDriver]::SendMessage($owner,0x11,[IntPtr]::Zero,[IntPtr]::Zero).ToInt64();if($sessionAllowed-ne0){throw 'Session shutdown accepted during recording'}
$null=[LabDriver]::PostMessage($owner,0x111,[IntPtr]4,[IntPtr]::Zero);$watch=[Diagnostics.Stopwatch]::StartNew();do{Start-Sleep -Milliseconds 50;$dialog=[LabDriver]::ByClass('#32770')}while($dialog-eq[IntPtr]::Zero-and$watch.ElapsedMilliseconds-lt3000);if($dialog-eq[IntPtr]::Zero){throw 'Busy Quit warning missing'};$warningStep=Get-LabWindowStep 'quit-recording-visible-warning' $dialog;$null=Invoke-LabButton $dialog 'OK';Activate-LabEditor $h;$editor.SetFocus()

Start-Sleep -Milliseconds 7550;$stop=Run-MediaCli 'stop';$processingStatus=Run-MediaCli 'status';$quitProcessing=Run-MediaCli 'quit';if($quitProcessing.exit-eq0){throw 'Quit accepted immediately after Stop'};$watch=[Diagnostics.Stopwatch]::StartNew();do{Start-Sleep -Milliseconds 100;$phase=Get-DictationPhase;$text=Read-Editor $editor}while(($phase-notmatch'^Koett Done'-or-not$text.Trim())-and$watch.ElapsedMilliseconds-lt20000)
$clipboard=[Windows.Forms.Clipboard]::GetText();$automatic=($text.TrimEnd([char[]]"`r`n")-ceq$clipboard-and$clipboard-match'Phoebe'-and([regex]::Matches($text,'Phoebe')).Count-eq1);$afterAuto=Get-LabFocus;$step=Get-LabWindowStep 'offline-notepad-automatic-once' $h
$db=$env:APPDATA+'\DybergCo\Koett\data\History.sqlite3';$historyBeforeRepeat=(Get-FileHash $db).Hash;$copy=Run-MediaCli 'copy-last';$paste=Run-MediaCli 'paste-last';Start-Sleep -Milliseconds 300;$repeated=Read-Editor $editor;$historyAfterRepeat=(Get-FileHash $db).Hash;$afterRepeat=Get-LabFocus;$browsersAfter=@(Get-Process msedge,msedgewebview2 -ErrorAction SilentlyContinue|Select-Object Id,ProcessName)
$runtimeModules=@((Get-Process -Id (Get-LabArtifact).pid).Modules|Where-Object {$_.ModuleName-match'(?i)webview|mshtml|chrome'}|Select-Object ModuleName)
@{quit_recording=$quitRecording;session_shutdown_allowed=$sessionAllowed;quit_warning=$warningStep;processing_status=$processingStatus;quit_processing=$quitProcessing;passed=($automatic-and([regex]::Matches($repeated,'Phoebe')).Count-eq2-and$historyBeforeRepeat-eq$historyAfterRepeat-and$focus.hwnd-eq$afterAuto.hwnd-and$focus.pid-eq$afterAuto.pid-and$focus.hwnd-eq$afterRepeat.hwnd-and@($browsersBefore|Where-Object {$_.ProcessName-eq'msedge'}).Count-eq0-and@($browsersAfter|Where-Object {$_.ProcessName-eq'msedge'}).Count-eq0-and$runtimeModules.Count-eq0);automatic_once=$automatic;browser_runtime_modules=$runtimeModules;runtime_override=($global:MediaDir+'\missing-browser-runtime');runtime_override_exists=(Test-Path ($global:MediaDir+'\missing-browser-runtime')); start=$start;stop=$stop;copy=$copy;paste=$paste;automatic_text=$text;repeated_text=$repeated;clipboard=$clipboard;history_before_repeat=$historyBeforeRepeat;history_after_repeat=$historyAfterRepeat;before=$focus;after_automatic=$afterAuto;after_repeat=$afterRepeat;browsers_before=$browsersBefore;browsers_after=$browsersAfter;network=@(Get-NetAdapter|Select-Object Name,Status,LinkSpeed);step=$step;artifact=Get-LabArtifact;fixture=$path}
